const out = [];
for (const item of $('Angebote aus Ordner lesen').all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const name = b.fileName || key;
    const ext = String(b.fileExtension || name.split('.').pop() || '').toLowerCase();
    let typ = 'unbekannt';
    if (ext === 'pdf') typ = 'pdf';
    else if (ext === 'docx') typ = 'docx';
    else if (['png', 'jpg', 'jpeg', 'webp', 'heic', 'tif', 'tiff'].includes(ext)) typ = 'bild';
    // DOCX ist technisch ein ZIP-Archiv. Der Node 'DOCX entpacken' erkennt es nur an der Endung .zip
    const data = typ === 'docx'
      ? { ...b, fileExtension: 'zip', mimeType: 'application/zip', fileName: name + '.zip' }
      : b;
    out.push({ json: { datei_name: name, datei_typ: typ }, binary: { data } });
  }
}
return out;

// Einheitliches Format je Datei. Dateien ohne lesbaren Text (z. B. OCR ausgefallen) werden aussortiert
// und spaeter im Bericht als 'nicht gelesen' genannt.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.error) continue;
  let text = j.text || '';
  // Gemini liefert den Text unter content.parts[].text
  if (!text && j.content && Array.isArray(j.content.parts)) {
    text = j.content.parts.map((p) => p.text || '').join('\n');
  }
  if (!text) text = j.xml || '';
  if (Array.isArray(text)) text = text.join('\n');
  if (text && typeof text === 'object') text = JSON.stringify(text);
  text = String(text).trim();
  if (!text) continue;
  let name = j.datei_name;
  let typ = j.datei_typ;
  if (!name) {
    try {
      const src = $('Dateien aufteilen').item.json;
      name = src.datei_name;
      typ = src.datei_typ;
    } catch (e) {}
  }
  out.push({ json: { datei_name: name || 'unbekannt', datei_typ: typ || 'unbekannt', text: text.slice(0, 20000) } });
}
return out;

const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  const key = Object.keys(bin).find((k) => {
    const fn = String(bin[k].fileName || '').toLowerCase();
    const dir = String(bin[k].directory || '').toLowerCase();
    return fn === 'document.xml' && (dir === '' || dir.includes('word'))
      || fn.endsWith('word/document.xml');
  });
  if (!key) continue;
  out.push({ json: item.json || {}, binary: { data: bin[key] } });
}
return out;

return $input.all().map((item) => {
  const xml = String(item.json.xml || '');
  const text = xml
    .replace(/<\/w:p>/g, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{2,}/g, '\n')
    .trim();
  return { json: { datei_name: item.json.datei_name, datei_typ: item.json.datei_typ, text: text } };
});

