const toIsoDate = (v) => {
  const s = String(v || '').trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const m = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{2,4})$/);
  if (m) {
    const y = m[3].length === 2 ? '20' + m[3] : m[3];
    return y + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  }
  return '';
};
const euro = (n) => (typeof n === 'number' ? n.toLocaleString('de-DE', { style: 'currency', currency: 'EUR' }) : 'Preis unklar');

const out = [];
for (const item of $input.all()) {
  const o = item.json.output || {};
  const hatPositionen = Array.isArray(o.positionen) && o.positionen.length > 0;
  const positionen = hatPositionen
    ? o.positionen
    : [{ leistung: 'Pauschalangebot (keine Einzelpositionen)', preis: typeof o.gesamtpreis === 'number' ? o.gesamtpreis : null }];
  for (const p of positionen) {
    out.push({
      json: {
        anbieter: o.anbieter || 'unbekannt',
        datum: toIsoDate(o.datum),
        projekt: o.projekt || '',
        leistung: p.leistung || '',
        preis: typeof p.preis === 'number' ? p.preis : null,
        position_text: (p.leistung || 'ohne Bezeichnung') + ': ' + euro(p.preis),
        gesamtpreis: typeof o.gesamtpreis === 'number' ? o.gesamtpreis : null,
        hinweise: o.hinweise || '',
      },
    });
  }
}
return out;

