// Eine Zeile für das Prüfformular: welche Dateien wurden im Ordner gefunden
const namen = $input.all().map((i) => (i.binary && i.binary.data && i.binary.data.fileName) || i.json.fileName || 'unbekannt');
return [{ json: { anzahl: namen.length, dateien: namen.join('<br>') } }];

// Vergleichsbericht als Markdown-Datei vorbereiten, inkl. Liste nicht gelesener Dateien
const alle = $('Dateien aufteilen').all().map((i) => i.json.datei_name);
const gelesen = $('Text vereinheitlichen').all().map((i) => i.json.datei_name);
const fehlend = alle.filter((n) => !gelesen.includes(n));
const kopf = '# Angebotsvergleich vom ' + $now.toFormat('dd.MM.yyyy HH:mm') + '\n\n'
  + 'Ausgewertet: ' + gelesen.length + ' von ' + alle.length + ' Dateien.'
  + (fehlend.length ? ' Nicht gelesen (bitte manuell prüfen): ' + fehlend.join(', ') + '.' : '') + '\n\n';
const text = kopf + String($input.first().json.output || '');
const binary = await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), 'Angebotsvergleich.md', 'text/markdown');
return [{ json: {}, binary: { data: binary } }];

// Gemini liefert nur den Text zurück. Dateinamen aus dem Bild-Zweig des Switch wieder anhängen (gleiche Reihenfolge).
const quelle = $('Nach Dateityp verzweigen').all(2);
return $input.all().map((item, i) => ({
  json: { ...item.json, datei_name: (quelle[i] && quelle[i].json.datei_name) || 'unbekannt', datei_typ: 'bild' },
}));
